-- ============================================
-- Test database initialization
-- ============================================

-- Sequence for Task.id
CREATE SEQUENCE IF NOT EXISTS tasks_id_seq
    START WITH 1
    INCREMENT BY 1;

-- ============================================
-- Tasks table
-- ============================================

CREATE TABLE IF NOT EXISTS phys_tasks
(
    id               BIGINT       NOT NULL DEFAULT nextval('tasks_id_seq'),
    section          VARCHAR(255),
    title            VARCHAR(255) NOT NULL,
    task_number      INTEGER      NOT NULL,
    self_task_number INTEGER      NOT NULL,
    task_level       VARCHAR(50)  NOT NULL,
    task_letter      CHAR(1)      NOT NULL,
    has_image        BOOLEAN      NOT NULL,
    page_number      INTEGER      NOT NULL,
    answer_type      VARCHAR(50)  NOT NULL,
    answer           VARCHAR(255) NOT NULL,
    page_link        VARCHAR(500) NOT NULL,
    task_text        TEXT         NOT NULL,
    class_number     INTEGER      NOT NULL,

    CONSTRAINT tasks_pkey PRIMARY KEY (id)
);

