        7),
       ('FORCES', 'Силы трения', 10, 14, 'HIGH', 'б', false, 45, 'SHORT', '0,4', 'kirik7.pdf#page=45',
        'На горизонтальной доске лежит железный брусок массой 4 кг. При его равномерном горизонтальном перемещении динамометр показывал 16 Н. Чему равно отношение силы трения к весу тела?',
        7),
       ('FORCES', 'Силы трения', 11, 14, 'HIGH', 'а', false, 45, 'DETAILED', '', 'kirik7.pdf#page=45',
