        7),
       ('FORCES', 'Силы трения', 12, 14, 'HIGH', 'а', false, 45, 'DETAILED', '', 'kirik7.pdf#page=45',
        'На столе лежит стопка из 7 одинаковых книг. В каком случае надо приложить меньшую силу: чтобы сдвинуть 6 верхних или вытянуть из стопки четвертую сверху книгу, придерживая (но не приподнимая) остальные?',
        7),
       ('FORCES', 'Силы трения', 12, 14, 'HIGH', 'б', false, 45, 'SHORT', '360 Н', 'kirik7.pdf#page=45',
        'Автомобиль, масса которого вместе с пассажирами равна 1,2 т, двигаясь равномерно по грунтовой дороге, развивает силу тяги, равную 0,03 его веса. Чему равна сила трения?',
        7);

