INSERT INTO phys_tasks (section, title, task_number, self_task_number, task_level, task_letter, has_image, page_number,
                        answer_type, answer, page_link, task_text, class_number)
VALUES ('BUOYANCY', 'Качественные задачи. Архимедова сила. Условия плавания', 1, 20, 'INITIAL', ' ', false, 69, 'SHORT',
        'не изменится', 'kirik7.pdf#page=69',
        'В сосуде с водой плавает кусок льда. Изменится ли уровень воды в сосуде, если лед растает?', 7),
       ('BUOYANCY', 'Качественные задачи. Архимедова сила. Условия плавания', 2, 20, 'INITIAL', ' ', false, 70, 'SHORT',
        'понизится', 'kirik7.pdf#page=70',
        'В сосуде с водой плавает кусок льда с вмерзшим в него стальным шариком. Изменится ли уровень воды в сосуде, когда лед растает?',
        7),
       ('BUOYANCY', 'Качественные задачи. Архимедова сила. Условия плавания', 3, 20, 'INITIAL', ' ', false, 70, 'SHORT',
        'не изменится', 'kirik7.pdf#page=70',
        'В сосуде с водой плавает кусок льда, в котором находится пузырек воздуха. Изменится ли уровень воды в сосуде, когда лед растает?',
        7),
       ('BUOYANCY', 'Качественные задачи. Архимедова сила. Условия плавания', 4, 20, 'INITIAL', ' ', false, 70, 'SHORT',
        'не изменится', 'kirik7.pdf#page=70',
        'В сосуде с водой плавает кусок льда, к которому примерзла пробка. Изменится ли уровень воды в сосуде, когда лед растает?',
        7),
       ('BUOYANCY', 'Качественные задачи. Архимедова сила. Условия плавания', 5, 20, 'INITIAL', ' ', false, 70, 'SHORT',
        'уменьшится', 'kirik7.pdf#page=70',
        'В сосуде с водой плавает брусок из льда. Как изменится глубина погружения бруска в воде, если поверх воды налить керосин?',
        7),
       ('BUOYANCY', 'Качественные задачи. Архимедова сила. Условия плавания', 6, 20, 'INITIAL', ' ', false, 70, 'SHORT',
        'понизится', 'kirik7.pdf#page=70',
        'В небольшом бассейне плавает лодка. Как изменится уровень воды в бассейне, если лежащий на дне лодки камень бросили в воду?',
        7),
       ('BUOYANCY', 'Качественные задачи. Архимедова сила. Условия плавания', 7, 20, 'INITIAL', ' ', false, 70, 'SHORT',
        'в бассейне; не изменится', 'kirik7.pdf#page=70',
        'В небольшом бассейне плавает полузатопленная лодка, причем уровень воды в лодке совпадает с уровнем воды в бассейне. Из лодки зачерпнули ведро воды и вылили в бассейн. Где после этого выше уровень воды — в лодке или в бассейне? Как изменился уровень воды в бассейне?',
        7),
       ('BUOYANCY', 'Качественные задачи. Архимедова сила. Условия плавания', 8, 20, 'INITIAL', ' ', false, 70, 'SHORT',
        'уменьшится', 'kirik7.pdf#page=70',
        'В большом сосуде на поверхности воды плавает стальная кастрюля. Изменится ли уровень воды в сосуде, если кастрюлю утопить?',
        7),
       ('BUOYANCY', 'Качественные задачи. Архимедова сила. Условия плавания', 9, 20, 'INITIAL', ' ', false, 70, 'SHORT',
        'не изменится', 'kirik7.pdf#page=70',
        'В сосуде с водой плавает шар, наполовину погрузившись в воду. Изменится ли глубина погружения шара, если этот сосуд с шаром перенести на планету, где сила тяжести в два раза больше, чем на Земле?',
        7),
       ('BUOYANCY', 'Качественные задачи. Архимедова сила. Условия плавания', 10, 20, 'INITIAL', ' ', false, 70,
        'SHORT', 'повысился бы', 'kirik7.pdf#page=70',
        'Как изменился бы уровень воды в океане, если бы растаяли все айсберги?', 7),
       ('BUOYANCY', 'Качественные задачи. Архимедова сила. Условия плавания', 11, 20, 'INITIAL', ' ', false, 70,
        'SHORT', 'понизится', 'kirik7.pdf#page=70',
        'В чаше с водой плавает спичечный коробок, на дне которого лежит небольшой камень. Изменится ли уровень воды в чаше, если камень вынуть из коробка и опустить в воду?',
        7),
       ('BUOYANCY', 'Качественные задачи. Архимедова сила. Условия плавания', 12, 20, 'INITIAL', ' ', false, 70,
        'SHORT', 'понизится', 'kirik7.pdf#page=70',
        'На поверхности воды в ведре плавает пустая медная кастрюля. Изменится ли уровень воды в ведре, если кастрюля утонет?',
        7);

